import sys, json, math, random
sys.path.insert(0,'/app')
import autopilot as A
R=json.loads(open('/tmp/opencode/rules.json').read()); W=json.loads(open('/tmp/opencode/map.json').read())
class T:
    def rules(s): return R
    def map(s): return W
    def telemetry_log(s): return [{"tick":0,"position":[20,20],"heading_deg":0,"battery":100,"terrain":"bedrock","wheel_odometry":0,"visual_odometry":0,"sampled_targets":[],"events":[]}]
M=A.Mission(T())
import time
# simple sim
bias=7.0; x,y=20.,20.; pk=[]; q={}; sampled=set(); bat=100
for cur in range(0,50):
    # execute command at cur
    c=q.get(cur); wo=0;vo=0;h=0
    bat-=0.5
    if c and c["action"]=="drive":
        bias+=random.gauss(0,1); hh=math.radians(c["heading_deg"]+bias+random.gauss(0,3))
        m=c["metres"]; s=0.02; 
        sand=any(a<=x<=cc and b<=y<=d for a,b,cc,d in M.sand); s=0.35 if sand else 0.02
        x+=math.cos(hh)*m*(1-s); y+=math.sin(hh)*m*(1-s); wo=m; vo=m*(1-s)*(1+random.gauss(0,.1)); h=c["heading_deg"]; bat-=m*(2 if sand else 1)
    if c and c["action"]=="sample":
        bat-=3
        for t in W["targets"]:
            if t["id"] not in sampled and math.hypot(t["x"]-x,t["y"]-y)<0.75: sampled.add(t["id"]); break
    pk.append({"tick":cur,"position":[x+random.gauss(0,.6),y+random.gauss(0,.6)],"heading_deg":h,"battery":bat,"wheel_odometry":wo,"visual_odometry":vo,"sampled_targets":sorted(sampled),"events":[]})
    for p in pk:
        if p["tick"]==cur-3: M.process_packet(p)
    T0=max(cur+4,M.last_exec+1)
    if T0<=49:
        t0=time.time(); cmd,info,tid=M.decide(T0); dt=time.time()-t0
        q[T0]=cmd; M.queue[T0]=cmd; M.last_exec=T0
        if tid: M.pending[tid]=T0
        print(cur,info,cmd,f"{dt:.2f}s true=({x:.2f},{y:.2f})")
print("sampled",sampled,"final",x,y,math.hypot(x-20,y-20),"bat",bat)
